def print_tree(root_dir, max_depth=3, current_depth=0):
    indent = '  ' * current_depth
    if current_depth >= max_depth:
        for item in sorted(os.listdir(root_dir)):
            path = os.path.join(root_dir, item)
            print(f"{indent}{'==' if os.path.isdir(path) else ''}{item}/" if os.path.isdir(path) else f"{indent}{'--' if os.path.isdir(path) else ''}{item}")
            if os.path.isdir(path):
                print_tree(path, max_depth, current_depth + 1)
        return

    for item in sorted(os.listdir(root_dir)):
        path = os.path.join(root_dir, item)
        if os.path.isdir(path):
            print(f"{indent}== {item}/")
            print_tree(path, max_depth, current_depth + 1)
        else:
            print(f"{indent}-- {item}")

